(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0006.js"] = [{"id":"glyph-kai-6751","script":"kai","character":"村","reading":"cūn","description":"cūn：(1)乡下聚居的处所～子。～塾（旧时农村中的私塾）。～民。\n(2)粗野～野。～俗。～话。～气。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-村"},{"id":"glyph-kai-6756","script":"kai","character":"杖","reading":"zhàng","description":"zhàng：(1)扶着走路的棍子手～。拐～。\n(2)泛指棍棒擀面～。禅～。\n(3)古代刑罚之一，用棍打～脊。\n(4)古同仗”，恃，凭倚。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杖"},{"id":"glyph-kai-675c","script":"kai","character":"杜","reading":"dù","description":"dù：(1)落叶乔木，果实圆而小，味涩可食，俗称杜梨”，亦称甘棠”、棠梨”。木材可做扁担或刻图章。\n(2)阻塞（sè），堵塞（sāi）～绝。～塞（sāi）。～门谢客，防微～渐。\n(3)姓～康（相传最早发明酿酒的人，文学作品中借指酒）。\n〔～撰〕凭自己的意思没有根据地编造。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杜"},{"id":"glyph-kai-675f","script":"kai","character":"束","reading":"shù","description":"shù：(1)捆住，系～缚。～装（整理行装）。～发（fà）。～之高阁。～手无策。\n(2)量词，用于捆在一起的东西～修（十条干肉，原指学生送给老师的礼物，后指给老师的报酬）。\n(3)聚集成一条的东西光～。电子～。\n(4)控制，限制～身。无拘无～。\n(5)事情的结末收～。结～。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-束"},{"id":"glyph-kai-6760","script":"kai","character":"杠","reading":"gàng；gāng","description":"gàng：(1)一种较粗的棍子～子。～杆。\n(2)在阅读或批改文字中作标记而画的粗直线。\ngāng：(1)旗杆。\n(2)小桥。\n(3)床前横木。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杠"},{"id":"glyph-kai-6761","script":"kai","character":"条","reading":"tiáo","description":"泛指一般长条形的物体\n⒈细长的枝枝～。柳～。荆～子。\n⒉细长的东西铁～。面～。纸～儿。布～子。\n⒊细长的形状～纹。～花布。\n⒋项目，分项目的～目。～款。～例。\n⒌秩序，层次～理。有～有理。\n⒍简短的信便～。字～子。\n⒎凭证借～。收～。\n⒏量词两～鱼。三～大路。四～新闻。\n①影响事物发生、存在或发展的因素客观～件。\n②要求，标准符合～件。\n③状况或基础身体～件。\n④约定或规定的应遵守之事项必须执行所定的～件。\n条tiāo 1.采摘。\n条dí 1.见\"条荡\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-条"},{"id":"glyph-kai-6765","script":"kai","character":"来","reading":"lái","description":"未来,将来\n⒈从甲方到乙方，跟\"去\"、\"往\"相对～电传。～到了天安门广场。\n⒉来到，发生～临。雨～了。～了险情。\n⒌在动词前，〈表〉要做某事我～帮你。大家都～献计献策。\n⒍在动词后，〈表〉趋向，继续做或曾经做过请进～。拿过～。一路走～。这衣服哪儿买～？\n⒎〈表〉粗略估计的数目两米～长。三十～岁。\n⒏助词。在一、二、三等数词后，〈表〉列举获得这一成果的原因一～是领导的关怀支持，二～是同志们的共同努力。\n⒐助词。诗歌里用着衬托，配合音节正月里～是新春。\n⒑［来回］\n①去了再回来。\n②往返一次。\n⒒［来往］\n①来和去。\n②交际。\n⒓［来历］人或事物的由来或经过。\n⒔［来源］事物的起源、根源。\n⒕［来着］助词。用于词尾。〈表〉已发生过的事昨天我们在这儿开会～着。\n来lài 1.慰劳;劝勉。 2.通\"赉\"。送给;赐予。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-来"},{"id":"glyph-kai-6768","script":"kai","character":"杨","reading":"yáng","description":"杨柳科杨属植物的泛称\n⒈比海更大的水域太平～。大西～。\n⒊充满，盛大～溢。\n①水大河水～ ～。〈引〉盛大，众多～ ～万言。\n②美好，高兴得意喜～ ～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杨"},{"id":"glyph-kai-676d","script":"kai","character":"杭","reading":"háng","description":"háng：(1)中国浙江省杭州市的简称～纺。～剧。\n(2)姓。\n(3)古同航”，渡河。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杭"},{"id":"glyph-kai-676f","script":"kai","character":"杯","reading":"bēi","description":"bēi：(1)盛酒、水、茶等的器皿～子。～盘狼藉。～中物（指酒）。\n(2)杯状的锦标奖～。～赛。夺～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杯"},{"id":"glyph-kai-6770","script":"kai","character":"杰","reading":"jié","description":"jié：(1)才能出众的人俊～。英雄豪～。\n(2)特异的，超过一般的～作。～出人才。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杰"},{"id":"glyph-kai-677e","script":"kai","character":"松","reading":"sōng","description":"常绿的针叶树，诗画中常用来象征坚韧。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-kai-677f","script":"kai","character":"板","reading":"bǎn","description":"同版”。木板\n泛指板状的扁平之物\n先设一铁板,其上以松脂、蜡和纸灰之\n①薄片状的较硬的物体三合～。\n②一种用来打拍子的民族乐器。\n③乐曲中的节拍快～、慢～。\n④呆板这个人不活泼，太～了。\n⑤硬得象板子似的地～了，苗长不好。\n⑥表情严肃他整天～着脸。\n【板鼓】打击乐器。鼓框用硬木合成，鼓面蒙以牛皮，鼓帮宽大，鼓心极小，用双竹签敲击鼓心、鼓帮或边心。音色清朗、响亮，是戏曲音乐、民间吹打乐中居重要地位的重要乐器。又叫小鼓、单皮鼓。\n【板胡】弓弦乐器。音色清脆、明亮、刚健、豪放，富有乡土气息，是地方戏曲的主要伴奏乐器。又叫梆胡。\n【板块构造学说】\n①法国地质学家勒比雄1968年提出的全球构造学说。认为地球的岩石圈不是整体一块，而是被一些活动的构造带-海岭、岛弧、平移大断层等所割裂的若干板块。\n【板块交界带】按板块构造学说划分的地球岩石圈的若干板块间的接触地带。多以洋中脊、转换断层、俯冲带和地缝合线为分界线。该地带是比较活跃的地带。\n【板式】根据不同节拍、节奏、速度等划分的唱腔格式。如京剧唱腔的板式分原板式、慢板式、快板式、自由板式等。\n【板眼】\n①民族音乐和戏曲中的节拍，每小节中最强的拍子叫板，其余的拍子叫眼。\n②比喻条理和层次他说得很有～，一点都不乱。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-板"},{"id":"glyph-kai-6781","script":"kai","character":"极","reading":"jí","description":"最高的地位\n特指君位\n顶点,最高处;最高最\n⒈顶端，最高点，尽头处～端。～点。登峰造～。〈引〉到极点乱～则治。暗～则光。\n⒉最，非常～重。～美好。穷凶～恶。\n⒊竭尽～力工作。～目远望。\n⒋指皇位登～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-极"},{"id":"glyph-kai-6784","script":"kai","character":"构","reading":"gòu","description":"字亦作搆”\n构成,造成\n⒊结怨，幻想，心思～怨。虚～。～思。\n构gōu 1.见\"构栏\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-构"},{"id":"glyph-kai-6789","script":"kai","character":"枉","reading":"wǎng","description":"wǎng：(1)弯曲，弯屈，引申为行为不合正道或违法曲断～道。矫～过正。贪脏～法。～己正人（自己身子不正，倒去矫正别人）。\n(2)冤屈～死。冤～。\n(3)屈就，用于别人，含敬意～驾（ａ．称对方来访自己；ｂ．请对方往访他人）。～顾（称对方来访自己）。～临（称对方来访自己）。\n(4)徒然，空，白～然。～自。～费心机。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枉"},{"id":"glyph-kai-6790","script":"kai","character":"析","reading":"xī","description":"xī：(1)分开条分缕～。分崩离～。\n(2)解释分～。剖～。～疑。赏～。～出（ａ．分析出来；ｂ．固体从液体或气体中分离出来）。辨～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-析"},{"id":"glyph-kai-6795","script":"kai","character":"枕","reading":"zhěn","description":"zhěn：(1)躺着时垫在头下的东西～头。落（lào）～。～席。\n(2)躺着的时候，把头放在枕头上或器物上～戈待旦。～藉（纵横相枕而卧）。\n(3)垫着～木（铁路上承受铁轨的横木）。～腕（写字运笔的一种方法，右手垫在左手上写）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枕"},{"id":"glyph-kai-6797","script":"kai","character":"林","reading":"lín","description":"lín：(1)长在一片土地上的许多树木或竹子树～。森～。～海。～薮（ａ．山林小泽；ｂ．喻丛集的处所）。\n(2)聚集在一起的同类的人或事物书～。艺～。碑～。儒～。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-林"},{"id":"glyph-kai-679a","script":"kai","character":"枚","reading":"méi","description":"méi：(1)树干伐其条～。\n(2)古代行军时防止士卒喧哗的用具，状如箸，衔在口中又如赴敌之兵，衔～疾走，不闻号令，但闻人马之行声”。\n(3)马鞭以～数（shǔ）阖（用马鞭指点着数门扇）。\n(4)量词，相当于个”，多用于形体小的东西一～别针。不胜～举（一个一个地举不完）。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枚"},{"id":"glyph-kai-679c","script":"kai","character":"果","reading":"guǒ","description":"guǒ：(1)某些植物花落后含有种子的部分～实。～品。～木。结～（ａ．结出果实；ｂ．事情的结局或成效）。\n(2)结局，与因”相对因～。成～。\n(3)坚决～决。～断。\n(4)确实，真的～真。如～。\n(5)充实，饱足～腹。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-果"},{"id":"glyph-kai-679d","script":"kai","character":"枝","reading":"zhī；qí","description":"zhī：(1)由植物主干上分出来的茎条树～。～干（gàn）。竹～。节外生～。～柯。～节（ａ．由一件事生发的其他问题；ｂ．细碎的，不重要的）。\n(2)量词，指杆形的一～铅笔。\n(3)古同支”，支持，分支。\nqí：古同歧”，岔。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枝"},{"id":"glyph-kai-67a2","script":"kai","character":"枢","reading":"shū","description":"木名,即刺榆\n泛指转轴\n半弦弧不满圜半径者,以矢\n⒈门上的转轴户～。\n⒉事物的关键或中心部分～纽。～要。中～神经。\n枢ōu 1.木名。即刺榆。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枢"},{"id":"glyph-kai-67a3","script":"kai","character":"枣","reading":"zǎo","description":"枣树所结的果实","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枣"},{"id":"glyph-kai-67aa","script":"kai","character":"枪","reading":"qiāng","description":"古时长柄有尖头的刺击武器\n武器名。火铳,火枪;发射子弹的火器。同鎗”\n⒈长矛长～。铁～§缨～。\n⒉发射弹丸的武器手～。冲锋～。\n⒊武装力量我们的原则是党指挥～，决不容许～指挥党。\n枪chēng 1.星名。参见\"枪星\"﹑\"枪棓\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枪"},{"id":"glyph-kai-67ab","script":"kai","character":"枫","reading":"fēng","description":"落叶乔木,春季开花,黄褐色。叶子掌状三裂,秋季变成红色\n槭属植物俗也称枫\n枫 fēng 枫树，也叫\"香枫\"。落叶乔木。春季开花。叶掌状三裂，秋季变红色。木材供建筑、制家具等用。果实和树脂可供药用。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枫"},{"id":"glyph-kai-67af","script":"kai","character":"枯","reading":"kū","description":"kū：(1)失去水分，水全没有了干～。～萎。～槁。～荣。～鱼衔索（串在绳索上的干鱼，形容存日不多）。\n(2)没趣味，无生趣～燥。～肠（喻枯涩贫乏的思路）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枯"},{"id":"glyph-kai-67b6","script":"kai","character":"架","reading":"jià","description":"jià：(1)用做支承的东西书～。衣～。绞～。\n(2)支承，搀扶～桥。～不住。～空。\n(3)互相殴打，争吵打～。劝～。\n(4)量词，多指有支柱或有机械的东西五～飞机。\n(5)捏造，虚构～词诬控。\n(6)古同驾”，凌驾。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-架"},{"id":"glyph-kai-67c4","script":"kai","character":"柄","reading":"bǐng","description":"bǐng：(1)植物的花、叶或果实跟枝茎连着的部分叶～。花～。\n(2)器物上的把儿刀～。勺～。\n(3)量词，用于有柄物一～伞。\n(4)喻在言行上被人抓住的材料把（bǎ）～。话～。\n(5)执掌～政（执掌政权）。～国。\n(6)权国～。民～。\n(7)根本谦，德之～也”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柄"},{"id":"glyph-kai-67cf","script":"kai","character":"柏","reading":"bǎi；bó；bò","description":"bǎi：(1)常绿乔木，叶鳞片状，结球果，有扁柏”、侧柏”、圆柏”、罗汉柏”等多种。木质坚硬，纹理致密。可供建筑及制造器物之用～露（柏树上的露水，据说用以洗眼，有明目的作用）。\n(2)姓。\nbó：〔～林〕德国的首都。\nbò：同檗”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柏"},{"id":"glyph-kai-67d0","script":"kai","character":"某","reading":"mǒu","description":"mǒu：(1)代替不明确指出的人、地、事、物等～人。～处。～国。\n(2)自称（代替我”或名字）～姓李。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-某"},{"id":"glyph-kai-67d1","script":"kai","character":"柑","reading":"gān","description":"gān：常绿灌木，果实圆形，似橘而大，赤黄色，味甜或酸甜，种类很多。树皮、叶、花、种子均可入药～橘（柑”、橘”、柚”、橙”等类果树或其果实）。广～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柑"},{"id":"glyph-kai-67d2","script":"kai","character":"柒","reading":"qī","description":"qī：七”的大写。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柒"},{"id":"glyph-kai-67d3","script":"kai","character":"染","reading":"rǎn","description":"rǎn：(1)把东西放在颜料里使着色～料。～色。～坊。～缸。印～。\n(2)感受疾病或沾上坏习惯或接触到什么～病。感～。传～。沾～。一尘不～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-染"},{"id":"glyph-kai-67d4","script":"kai","character":"柔","reading":"róu","description":"róu：(1)植物初生而嫩～荑（初生嫩芽，喻女子白嫩的手）。\n(2)软，不硬～软。～韧。～嫩。～滑。\n(3)软弱，与刚”相对～懦。～弱。刚～相济。\n(4)温和～顺。～和。～曼（柔和妩媚）。～情。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柔"},{"id":"glyph-kai-67dc","script":"kai","character":"柜","reading":"guì；jǔ","description":"jǔ：〔～柳〕落叶乔木，羽状复叶，小叶长椭圆形，枝韧，可以编筐。性耐湿、耐碱，可固沙，多栽植在路旁做行道树。亦称元宝枫”、杞柳”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柜"},{"id":"glyph-kai-67e0","script":"kai","character":"柠","reading":"níng","description":"木名\n柠檬","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柠"},{"id":"glyph-kai-67e5","script":"kai","character":"查","reading":"chá；zhā","description":"chá：(1)考察检～。调～。～验。～访。～阅。\n(2)古同槎”，水中浮木。\nzhā：(1)姓。\n(2)同楂”。\n(3)古同渣”，渣滓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-查"},{"id":"glyph-kai-67ec","script":"kai","character":"柬","reading":"jiǎn","description":"jiǎn：(1)信件、名片、帖子等的泛称请～。书～。\n(2)简选，拣～寄（盐并委托职务）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柬"},{"id":"glyph-kai-67f1","script":"kai","character":"柱","reading":"zhù","description":"zhù：(1)建筑物中直立的起支撑作用的构件～子。～石。顶梁～。\n(2)形状像柱子的东西，或作用重要如柱子的水～。～臣（对国家有重要作用的臣子）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柱"},{"id":"glyph-kai-67f3","script":"kai","character":"柳","reading":"liǔ","description":"liǔ：(1)落叶乔木或灌木，枝柔韧，叶狭长，春天开黄绿色花，种子上有白色毛状物，成熟后随风飞散，种类很多，有垂柳”、河柳”、杞柳”等～条。～絮。～暗花明。\n(2)星名，二十八宿之一。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柳"},{"id":"glyph-kai-67f4","script":"kai","character":"柴","reading":"chái","description":"chái：(1)烧火用的草木～草。～火。～门。火～。木～。\n(2)烧柴祭天～于上帝”。\n(3)瘦，不松软～鸡。～心儿。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柴"},{"id":"glyph-kai-67ff","script":"kai","character":"柿","reading":"shì","description":"shì：落叶乔木，果实为扁圆形或圆椎形浆果，黄或橙红色，可食～子。～饼。～霜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柿"},{"id":"glyph-kai-6805","script":"kai","character":"栅","reading":"shān；zhà；shi；cè","description":"zhà：用竹木铁条等做成的阻拦物～栏。～子。\nshān：〔～极〕多极电子管靠阴极的一个电极。\n〔光～〕产生光的衍射图像的光学仪器。\nshi：〔大～栏〕方言，中国北京市前门外一条热闹街市名。\ncè：〔上～〕\n〔下～〕地名，均在中国广东省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-栅"},{"id":"glyph-kai-6807","script":"kai","character":"标","reading":"biāo","description":"末梢;事物的枝节或表面。与本”相对\n顶端\n柱竿之类","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-标"},{"id":"glyph-kai-6808","script":"kai","character":"栈","reading":"zhàn","description":"古代用竹木条横排编成车箱的轻便车子\n车乘栈车\n⒈关养牲畜的棚或栅栏羊～。\n⒉存放货物或供旅客住宿的地方货～。客～。\n⒊〈古〉在险峻绝壁的山上用竹木等架设的道路～道。\n⒋〈古〉竹木做成的车～车。\n栈zhǎn 1.古代乐器。小钟。\n栈chén 1.见\"栈栈\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-栈"},{"id":"glyph-kai-680b","script":"kai","character":"栋","reading":"dòng","description":"②量词。多用于房屋两～楼。\n【栋梁之材】比喻担负国家重任的人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-栋"},{"id":"glyph-kai-680f","script":"kai","character":"栏","reading":"lán","description":"饲养家畜的圈\n报纸或刊物中有固定标题或特写的部分\n一面墙壁或特制的告示牌,用以张贴通知、证\n⒈遮挡的东西竹～。铁～。花编～。\n⒉家畜的圈猪～。\n栏liàn 1.木名。即楝。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-栏"},{"id":"glyph-kai-6811","script":"kai","character":"树","reading":"shù","description":"种植\n⒈木本植物的总称～木。六棵大～。松～。柏～。植～造林。\n⒉种植，栽培，培养～植草木。十年～木，百年～人。\n⒊竖立，建立～立。～雄心。～新风。独～一帜。\n⒋量词。株，棵种甘桔千～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-树"},{"id":"glyph-kai-6813","script":"kai","character":"栓","reading":"shuān","description":"shuān：(1)器物上可以开关的机件枪～。\n(2)塞子或作用跟塞子相仿的东西～塞。血～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-栓"},{"id":"glyph-kai-6816","script":"kai","character":"栖","reading":"qī；xī","description":"qī：(1)鸟禽歇宿夫以鸟养养鸟者，宜～之深林”。\n(2)居留，停留～身。～息。～止。～遁（隐居，遁世）。～迟（游息，居住）。\nxī：〔～～〕形容不安定。\n〔～遑〕ａ．忙碌不安，到处奔波；ｂ．被迫。均亦作栖皇”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-栖"},{"id":"glyph-kai-6817","script":"kai","character":"栗","reading":"lì","description":"lì：(1)落叶乔木，果实为坚果，称栗子”，味甜，可食～色。火中取～。\n(2)发抖，因害怕或寒冷肢体颤动战～。\n(3)坚实缜密以～”。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-栗"},{"id":"glyph-kai-6821","script":"kai","character":"校","reading":"xiào；jiào","description":"xiào：(1)学堂，专门进行教育的机构～园。～长。\n(2)军衔的一级，在将”之下，尉”之上。\n(3)古代军队编制单位～尉（统带一校的军官）。\njiào：(1)比较～场。\n(2)查对、订正～勘。～订。～对。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-校"},{"id":"glyph-kai-682a","script":"kai","character":"株","reading":"zhū","description":"zhū：(1)露出地面的树根守～待兔。～连。～戮。\n(2)棵儿，指整个的植物体植～。\n(3)量词，指植物一～桃树。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-株"},{"id":"glyph-kai-6837","script":"kai","character":"样","reading":"yàng","description":"假借为像”。式样\n形状,模样\n⒈形状～子。模～儿。走了～。\n⒉种类这两～。那几～。一个～儿。～ ～都行。\n⒊作为标准或代表的榜～。～板。～品儿。货～子。\n样xiàng 1.橡实。即栎实。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-样"},{"id":"glyph-kai-6838","script":"kai","character":"核","reading":"hé；hú","description":"hé：(1)果实中坚硬并包含果仁的部分桃～。杏～。\n(2)像核的东西～细胞。～酸。～心（中心）。结～。原子～。～子。～反应。～武器。\n(3)仔细地对照、考察～定。～计。～实。～算。～查。\n(4)翔实正确其文直，其事～。\nhú：义同（一）①②，用于某些口语词，如杏核儿”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-核"},{"id":"glyph-kai-6839","script":"kai","character":"根","reading":"gēn","description":"gēn：(1)高等植物茎干下部长在土里的部分～植。～茎。～瘤。～毛。～雕。须～。块～。扎～。叶落归～。\n(2)物体的基部和其他东西连着的部分～底。～基。墙～儿。\n(3)事物的本源～源。～由。～本。知～知底。\n(4)彻底～除。～究。～治。\n(5)依据，作为根本～椐。\n(6)量词，指长条的东西两～筷子。\n(7)数学上称一数开平方所得的值为平方根”，开立方所得的值为立方根”。\n(8)数学上指代数方程式内未知数的值。\n(9)化学上指带电的基氨～。硫酸～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-根"},{"id":"glyph-kai-683c","script":"kai","character":"格","reading":"gé","description":"gé：(1)划分成的空栏和框子～子纸。方～儿布。\n(2)法式，标准～局。～律。～式。～言∠～。资～。\n(3)表现出来的品质～调。风～。人～。国～。性～。\n(4)阻碍，隔阂～～不入。\n(5)击，打～斗。～杀。\n(6)推究～致。\n(7)树的长枝。\n(8)至，来～于上下。\n(9)感通～于皇天。\n(10)变革，纠正～非。\n(11)某些语言中的语法范畴。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-格"},{"id":"glyph-kai-683d","script":"kai","character":"栽","reading":"zāi","description":"zāi：(1)移植～树。～植。～花。～培。\n(2)安上，插上～绒。～赃。\n(3)秧子，可以移植的植物的幼苗桃～。树～子。\n(4)跌倒～跟头。\n(5)指失败或出丑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-栽"},{"id":"glyph-kai-6842","script":"kai","character":"桂","reading":"guì","description":"guì：(1)中国广西壮族自治区的别称～剧。～系军阀。\n(2)姓。\n〔～花〕常绿小乔木或灌木，叶椭圆形，开白色或暗黄色小花，有特殊的香气，供观赏，亦可做香料，通称木犀”；简称桂”，如金～”，～子飘香”、～轮”（月的别称，相传月中植桂花。亦称桂魄”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桂"},{"id":"glyph-kai-6843","script":"kai","character":"桃","reading":"táo","description":"táo：(1)落叶小乔木，品种很多，果实略呈球形，表面有短绒毛，味甜，有大核，核仁可入药～儿。～李（喻所教的学生）。～李不言，下自成蹊（喻实至名归，尚事实，不尚虚名）。世外～源（指不受外界影响的地方或幻想中的美好世界）。\n(2)形状像桃子的棉～儿。\n(3)指核桃～仁。～酥。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桃"},{"id":"glyph-kai-6846","script":"kai","character":"框","reading":"kuàng","description":"kuàng：(1)嵌在墙上为安装门窗用的架子门～。\n(2)镶在器物的外围有支撑作用或保护作用的东西～子。镜～儿。\n(3)周围的圈儿～～（亦喻原有的范围、固有的和固执的看法或印象）。\n(4)在文字、图片的周围加上线条把这两个字～起来。\n(5)限制，约束别～得太死。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-框"},{"id":"glyph-kai-6848","script":"kai","character":"案","reading":"àn","description":"àn：(1)长形的桌子或架起来代替桌子用的长木板～子。～板。书～。条～。拍～而起。\n(2)提出计划、方法和建议的文件或记录档～。备～。议～。提～。方～。有～可查。～卷。～牍。\n(3)事件，特指涉及法律问题的事件惨～。血～。～件。～例。～犯。破～。\n(4)古代有短脚盛食物的木托盘举～齐眉（形容夫妻相敬）。\n(5)同按”⑤　　。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-案"},{"id":"glyph-kai-684c","script":"kai","character":"桌","reading":"zhuō","description":"zhuō：(1)几（jī）案，可用于饮食、读书、写字～案。饭～。方～。\n(2)量词三～客人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桌"},{"id":"glyph-kai-6850","script":"kai","character":"桐","reading":"tóng","description":"tóng：〔泡（pāo）～〕落叶乔木，叶大，开白色或紫色花，木材可做琴、船、箱等物。\n〔梧～〕见梧”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桐"},{"id":"glyph-kai-6851","script":"kai","character":"桑","reading":"sāng","description":"sāng：(1)落叶灌木，叶子可以喂蚕，果穗味甜可食，木材可制家具或农具，皮可造纸，叶、果均可入药。中国大部分地区都有种植～葚。～农。～梓（喻乡里，故乡）。沧海～田（形容世事变迁很大）。～榆暮景。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桑"},{"id":"glyph-kai-6854","script":"kai","character":"桔","reading":"jú；jié","description":"jié：〔～梗〕多年生草本植物，叶卵形或卵状披针形，花暗蓝色或紫色，供观赏。根可入药。\njú：橘”俗作桔”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桔"},{"id":"glyph-kai-6863","script":"kai","character":"档","reading":"dàng","description":"档案,排列或分类过的卡片或文件卷宗\n存放案卷用的带格子的橱\n按重要性、质量或价值排列的级别\n指曲艺、杂技表演一个节目\n①存放案卷用的带格子的架子或橱柜归～。\n②档案，分类保存的文件、材料等查～。\n【档案】具有使用价值、分类保存的各种文件材料。中国从夏、商起，就有了档案。\n【档案学】揭示档案和档案工作的本质和发展规律，研究档案的管理、利用的原则和方法的学科。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-档"},{"id":"glyph-kai-6865","script":"kai","character":"桥","reading":"qiáo","description":"器物上的横杆\n木名\n架桥,修桥\n桥jiāo 1.桔槔。井上汲水工具。或指桔槔上的衡木。 2.通\"憍\"。骄傲。参见\"桥泄\"。\n通\"矫\"。矫正。 3.通\"矫\"。伪，虚假。参见\"桥言\"。 4.通\"挢\"。翘起;伸出。 5.劲疾。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桥"},{"id":"glyph-kai-6866","script":"kai","character":"桦","reading":"huà","description":"桦木，落叶乔木，树皮多呈白色或灰色。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-6868","script":"kai","character":"桨","reading":"jiǎng","description":"划船的用具，长柄，一端呈片状，用来拨水行船。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-6869","script":"kai","character":"桩","reading":"zhuāng","description":"储物备用的内库\n旧时赌博头家称坐庄”或称做桩”\n多指事情的件数。如一桩大冤案\n储备;储存\n除刘宝私财还宝外,余并桩充军须。╠\n⒈一端插入地里的木柱或石柱木～。桥～子。拴马～。\n⒉量词。指事情的件数那～事。几～案件。一～一～的弄清楚。\n桩chōng 1.撞击。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桩"},{"id":"glyph-kai-6876","script":"kai","character":"桶","reading":"tǒng","description":"tǒng：(1)盛水或其他东西的器具，深度较大，用金属、木材或塑料等制成水～。饭～。马～。塑料～。\n(2)形状像桶的皮～（做皮衣用的成件的毛皮）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桶"},{"id":"glyph-kai-6881","script":"kai","character":"梁","reading":"liáng","description":"liáng：(1)架在墙上或柱子上支撑房顶的横木，泛指水平方向的长条形承重构件房～。栋～。～上君子（指窃贼）。\n(2)桥桥～。津～（渡口和桥梁，借指学习的门径）。\n(3)器物、身体或其他物体上中间高起的部分鼻～。山～。车～。\n(4)中国战国时期国名，魏国于公元前361年迁都大梁（今河南省开封市）后，改称梁”。\n(5)中国朝代名（ａ．南朝之一；ｂ．五代之一）。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梁"},{"id":"glyph-kai-6885","script":"kai","character":"梅","reading":"méi","description":"méi：(1)落叶乔木，品种很多，性耐寒，初春开花，有白、红等颜色，分五瓣，香味很浓，果实球形，味酸～花。～子。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梅"},{"id":"glyph-kai-6886","script":"kai","character":"梆","reading":"bāng","description":"bāng：象声词，敲打木头的声音～～～的敲门声。\n〔～子〕ａ．打更用的响器；ｂ．打击乐器，用于戏曲、乐曲伴奏；ｃ．戏曲声腔之一，如河北～～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梆"},{"id":"glyph-kai-6897","script":"kai","character":"梗","reading":"gěng","description":"gěng：(1)植物的枝或茎菜～子。\n(2)直，挺立～着脖子。\n(3)正直，直爽～直。\n(4)阻塞，妨碍～塞（sè）。～阻。心肌～死。\n(5)大略～概。\n(6)有刺的草木～榆（刺榆）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梗"},{"id":"glyph-kai-68a2","script":"kai","character":"梢","reading":"shāo；sào","description":"shāo：(1)树枝或条状物的末端树～。末～。～头。～林。\n(2)末尾眉～。收～。\n(3)古代奏乐时拿的竿子。\n(4)古同艄”，船舵尾。\nsào：(1)像圆锥体的形状。\n(2)柱形物体的横剖面向一端面逐渐缩小的形式。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梢"},{"id":"glyph-kai-68a6","script":"kai","character":"梦","reading":"mèng","description":"⒈睡眠时局部大脑皮层还未停止活动，因体内、外各种刺激而引起大脑内的表现影像日有所思，夜有所～。\n⒉指做梦～见。～游。\n⒊〈喻〉虚幻～幻。～想。～求。\n梦méng 1.不明。 2.昏乱。见\"梦梦\"。 3.最细的雨。 4.用同\"蒙\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梦"},{"id":"glyph-kai-68a7","script":"kai","character":"梧","reading":"wú","description":"wú：〔～桐〕落叶乔木。木质轻而坚韧，可制乐器和各种器具，种子可食，亦可榨油。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梧"},{"id":"glyph-kai-68a8","script":"kai","character":"梨","reading":"lí","description":"lí：落叶乔木或灌木，果实是普通水果，品种很多～膏。广～。鸭～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梨"},{"id":"glyph-kai-68ad","script":"kai","character":"梭","reading":"suō","description":"suō：(1)织布时往返牵引纬线（横线）的工具，两头尖，中间粗，像枣核形～子（ａ．织布工具；ｂ．机关枪、冲锋枪的子弹夹子；ｃ．量词，如打了一～～子弹”）。\n(2)形状像梭的～镖。～子蟹。\n(3)喻不断地来往～巡。穿～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梭"},{"id":"glyph-kai-68af","script":"kai","character":"梯","reading":"tī","description":"tī：(1)登高用的器具、设备～子。楼～。木～。软～。电～。云～。阶～。\n(2)形状或作用像梯子的～田。～级。～形。～队（亦泛指工作中层层递补的力量）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梯"},{"id":"glyph-kai-68b0","script":"kai","character":"械","reading":"xiè","description":"xiè：(1)器物，家伙器～。机～。\n(2)武器～斗。军～。缴～投降。\n(3)木枷和镣铐之类的刑具～系。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-械"},{"id":"glyph-kai-68b3","script":"kai","character":"梳","reading":"shū","description":"shū：(1)整理头发的用具木～。角～。\n(2)用梳子整理头发～头。～洗（梳头洗脸）。～妆。～辫子（喻把纷繁的事项、问题等进行分析归类）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梳"},{"id":"glyph-kai-68c0","script":"kai","character":"检","reading":"jiǎn","description":"法式,法度\n品行;节操\n约束,限制\n⒈查，查看，查验～字。～修。～收。\n⒉收敛，约束～点。言行失～。\n⒊法度，法则，方式定～。节奏同～。\n①仔细地查看。\n②查考。\n③检讨。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-检"},{"id":"glyph-kai-68c9","script":"kai","character":"棉","reading":"mián","description":"mián：一年生草本植物，果实像桃，内有白色的纤维和黑褐色的种子。纤维供纺织及絮衣被用。种子可榨油，供食用和工业用（通称棉花”）～袄。～被。～布。～纺。～桃。～纱。～线。～絮。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-棉"},{"id":"glyph-kai-68cb","script":"kai","character":"棋","reading":"qí","description":"qí：文娱项目的一类，亦特指棋子”象～。围～。～盘。～道。星罗～布。举～不定（喻拿不定主意）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-棋"},{"id":"glyph-kai-68cd","script":"kai","character":"棍","reading":"gùn；hùn","description":"gùn：(1)棒～子。～术。～棒。木～。铁～。\n(2)称坏人恶～。赌～。\nhùn：(1)捆扎～申椒与菌桂兮，赴江湖而沤之”。\n(2)古同混”，混成。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-棍"},{"id":"glyph-kai-68d2","script":"kai","character":"棒","reading":"bàng","description":"bàng：(1)棍子木～。～子（ａ．棍子；ｂ．玉米的别称）。～槌。～冰。～球。～喝（hè）。\n(2)体力强，能力大，成绩好，水平高功课～。身体～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-棒"},{"id":"glyph-kai-68d5","script":"kai","character":"棕","reading":"zōng","description":"zōng：〔～榈〕常绿乔木，茎直立不分枝，叶大，木材可制器具，通称棕树”。\n〔～毛〕棕榈叶鞘的纤维，简称棕”，如～绳”，～绷”，～帚”，～编”。\n〔～熊〕哺乳动物，体大，毛棕褐色。掌和肉可食，皮可制皮褥，胆可入药。亦称马熊”、罴”；通称人熊”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-棕"},{"id":"glyph-kai-68d8","script":"kai","character":"棘","reading":"jí","description":"jí：(1)酸枣树，茎上多刺；泛指有刺的苗木荆～。～手（喻事情难办）。～刺。～针。\n(2)针形的刺～皮动物。\n(3)古同戟”，兵器。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-棘"},{"id":"glyph-kai-68da","script":"kai","character":"棚","reading":"péng","description":"péng：用竹木搭成架子，上面覆盖席、布等做成的遮蔽风雨日光的东西或简陋的小屋天～。帐～。窝～。～车。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-棚"},{"id":"glyph-kai-68e0","script":"kai","character":"棠","reading":"táng","description":"táng：姓。\n〔～梨〕ａ．落叶乔木，果实略呈球形。可以用作嫁接各种梨的砧木；ｂ．这种植物的果实，均亦称杜梨”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-棠"},{"id":"glyph-kai-68ee","script":"kai","character":"森","reading":"sēn","description":"sēn：(1)树木众多，引申为众多、繁盛～林。～立。～～。～然。～郁。\n(2)幽深可怕的样子阴～。～邃。\n(3)严整的样子～严。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-森"},{"id":"glyph-kai-68f1","script":"kai","character":"棱","reading":"léng；lēng；líng","description":"léng：(1)物体上的条状突起，或不同方向的两个平面相连接的部分～角。瓦～。～椎（多面体的一种）。三～镜。模～两可。\n(2)神灵之威，威势威～。\nlēng：〔不～登〕口语赘词，用于某些形容词后，含厌恶意，如傻～～～”。\nlíng：〔穆～〕地名，在中国黑龙江省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-棱"},{"id":"glyph-kai-68f5","script":"kai","character":"棵","reading":"kē","description":"kē：量词，用于植物一～树。一～草。几～白菜。\n〔棵儿（kēr）〕植物的大小，如树～～很大”，拣～～大的菜拔”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-棵"},{"id":"glyph-kai-68fa","script":"kai","character":"棺","reading":"guān","description":"guān：装殓死人的器具～材。～木。～椟。～椁。盖～论定。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-棺"},{"id":"glyph-kai-6905","script":"kai","character":"椅","reading":"yǐ；yī","description":"yǐ：有靠背的坐具～子。坐～。木～。躺～。\nyī：落叶乔木，木材可以制器物。亦称山桐子”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-椅"},{"id":"glyph-kai-690d","script":"kai","character":"植","reading":"zhí","description":"zhí：(1)栽种种～。培～。栽～。～树。\n(2)树立～立。～志（立志）。\n(3)戮住，竖起～耳。\n(4)生物的一大类，谷类、花草、树木等的统称～物。～被。～保。\n(5)古代军中监督工事的将官华元为～，巡功。”","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-植"},{"id":"glyph-kai-690e","script":"kai","character":"椎","reading":"zhuī；chuí","description":"zhuī：构成高等动物背部中央骨柱的短骨～骨。脊～。颈～。胸～。尾～。\nchuí：(1)敲打东西的器具铁～。木～。鼓～。\n(2)敲打，用椎打击～鼓。～杀。～心泣血（形容极度悲痛的样子）。\n(3)愚钝，朴实～鲁。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-椎"},{"id":"glyph-kai-6912","script":"kai","character":"椒","reading":"jiāo","description":"jiāo：〔花～〕ａ．落叶灌木或小乔木，果实球形，暗红色，种子黑色，可供药用或调味；ｂ．这种植物的果实，简称椒”，如～盐”。～酒”。～桂”（常用来喻贤人）。\n〔胡～〕ａ．常绿藤本植物，果实球形，红色，成熟后红黑色，味辛辣，可供药用或调味；ｂ．这种植物的果实。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-椒"},{"id":"glyph-kai-692d","script":"kai","character":"椭","reading":"tuǒ","description":"指某些长圆形的容器","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-椭"},{"id":"glyph-kai-6930","script":"kai","character":"椰","reading":"yē","description":"yē：〔～子〕ａ．常绿乔木，产于热带，树干很高，核果椭圆形，果肉白色多汁，可食，亦可榨油。果壳可做各种器皿，叶可盖屋、编席、制扇等；ｂ．这种植物的果实，简称椰”，如～油”，～杯”，～雕”，～蓉”，～胡”（用半个椰壳制成的胡琴）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-椰"},{"id":"glyph-kai-693f","script":"kai","character":"椿","reading":"chūn","description":"chūn：〔香～〕落叶乔木，嫩枝叶有香味，可食。简称椿”，如～芽”，～龄”（祝人长寿之辞），～庭”（古称父亲），～萱”（父母的代称）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-椿"},{"id":"glyph-kai-695a","script":"kai","character":"楚","reading":"chǔ","description":"chǔ：(1)落叶灌木，鲜叶可入药。枝干坚劲，可以做杖。亦称牡荆”。\n(2)古代的刑杖，或学校扑责学生的小杖捶～。夏～。～掠（拷打）。～挞（拷打）。\n(3)中国春秋时国名～天（楚地的天空。因楚在南方，亦泛指南方天空）。～声。～歌（楚人之歌）。～狂。～腰（泛称女子的细腰）。～辞。四面～歌。～材晋用（指使用他国人才，或指人才外流）。\n(4)指中国湖北省和湖南省，特指湖北省～剧。\n(5)痛苦苦～。痛～。凄～。酸～。\n(6)清晰，鲜明，整洁清～。衣冠～～。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-楚"},{"id":"glyph-kai-6977","script":"kai","character":"楷","reading":"kǎi；jiē","description":"kǎi：(1)法式，模范～模。～范。～则。～式。\n(2)汉字的一种书体～书。正～。小～。～体。\njiē：落叶乔木，木材可制器具，种子可榨油，树皮和叶子可制栲胶。亦称黄连木”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-楷"},{"id":"glyph-kai-697c","script":"kai","character":"楼","reading":"lóu","description":"楼房的一层\n房间上部空间附设的可供藏物或住人的分层结构\n建筑在高处的建筑物\n⒈两层及两层以上的房屋～房。高～。又指楼房的一层我住二～。他住四～。\n⒉建筑物有上层结构的鼓～。城～。\n楼lǘ 1.见\"离楼\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-楼"},{"id":"glyph-kai-6982","script":"kai","character":"概","reading":"gài","description":"gài：(1)大略，总括大～。～论。～述。～貌。梗～。～要。～算。～括。～念（反映对象的本质属性的思维形式）。～率（概率论的基本概念。用来表示随机事件发生可能性大小的量称为此事件的概率”。亦称或然率”、几率”）。以偏～全。\n(2)情况，景象胜～（胜景，美丽的景色）。\n(3)一律一～而论。\n(4)气度，节操；气～。\n(5)刮平斗、斛用的小木板。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-概"},{"id":"glyph-kai-6984","script":"kai","character":"榄","reading":"lǎn","description":"木名。橄榄的省称","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-榄"},{"id":"glyph-kai-6986","script":"kai","character":"榆","reading":"yú","description":"yú：(1)落叶乔木，实扁圆，木材坚实，可制器具或供建筑用～荚。～钱儿（即榆荚”，像小铜钱）。～面（以榆皮磨制成粉，用为黏剂）。～塞（古称边塞植榆，故称边塞为榆塞”）。桑～暮景。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-榆"},{"id":"glyph-kai-6994","script":"kai","character":"榔","reading":"láng","description":"láng：〔～头〕锤子。\n〔～榆〕落叶乔木，木材坚硬致密。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-榔"},{"id":"glyph-kai-6995","script":"kai","character":"榕","reading":"róng","description":"róng：(1)常绿乔木，气根细瘦，树冠大，隐花果生于叶腋，近扁球形。生长在热带和亚热带，木材可制器具。\n(2)中国福建省福州市的别称～城。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-榕"},{"id":"glyph-kai-699c","script":"kai","character":"榜","reading":"bǎng；bàng","description":"bǎng：张贴出来的文告或名单～帖（官府的公告）§～。张～。光荣～。～文。发～。～眼（科举时代称殿试考取一甲第二名的人）。～书（原指写在宫阙门额上的大字，后泛指招牌一类的大型字）。\nbàng：摇船的用具～人（船工）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-榜"},{"id":"glyph-kai-69a8","script":"kai","character":"榨","reading":"zhà","description":"zhà：(1)压出物体里汁液的器具油～。酒～。～床。\n(2)用力把物体里的汁液压出来，引申为逼取他人的财物～油。～取。压～。\n〔～菜〕ａ．二年生草本植物，芥菜的变种，茎膨大成瘤状，可食；ｂ．用这种植物的茎加辣椒、香料等腌制而成的副食品。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-榨"},{"id":"glyph-kai-69b4","script":"kai","character":"榴","reading":"liú","description":"liú：〔石～〕落叶灌木或小乔木，一般开红花，果实球状，内有很多种子，种子上的肉可食，根和皮可入药（榴”读轻声）。\n〔～莲〕常绿乔木，叶子长椭圆形。果实球形，有硬刺，可食。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-榴"},{"id":"glyph-kai-69d0","script":"kai","character":"槐","reading":"huái","description":"huái：(1)落叶乔木。木材可供建筑和制家具。花蕾可做黄色染料～火（用槐木取火）。～序。～楝（ａ．中国周代朝廷种三槐九棘，公卿大夫分坐其下，后因以槐棘”指三公或三公之位；ｂ．指听讼的处所。均亦称棘槐”）。～鼎（喻三公）。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-槐"},{"id":"glyph-kai-69db","script":"kai","character":"槛","reading":"kǎn；jian","description":"槛车;囚车\n⒉栏杆，栏板。\n⒊见kǎn。\n⒉见jiàn。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-槛"},{"id":"glyph-kai-69fd","script":"kai","character":"槽","reading":"cáo","description":"cáo：(1)一种长方形或正方形的较大的盛东西的器具～子。水～。酒～。～坊。\n(2)特指用来盛饲料喂牲畜的器具马～。猪食～。～头。\n(3)槽状的～钢。～铁。～牙。\n(4)两边高起，中间凹下物体的凹下部分河～。在石头上凿个～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-槽"},{"id":"glyph-kai-6a1f","script":"kai","character":"樟","reading":"zhāng","description":"zhāng：常绿乔木，木质坚硬细致，有香气，做成箱柜可防蠹虫香～（樟树）。～脑（由樟树的根、茎、枝、叶蒸馏而制成的白色结晶体，可入药。亦是工业原料。亦称潮脑”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-樟"},{"id":"glyph-kai-6a21","script":"kai","character":"模","reading":"mó；mú","description":"mó：(1)法式，规范，标准～范。～式。楷～。～型。～本。～压。\n(2)仿效～仿（亦作摹仿”）。～拟（亦作摹拟”）。～写。\n(3)特指模范”劳～。英～。\nmú：用压制或浇注的方法使材料成为一定形状的工具～子。～板。～具。\n〔～样〕ａ．人的长相或装束打扮的样子；ｂ．表示约略的时间、怎么办；ｃ．描摹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-模"},{"id":"glyph-kai-6a2a","script":"kai","character":"横","reading":"héng；hèng","description":"héng：(1)跟地面平行的，与竖”、直”相对～梁。～楣。～额。～幅。～批。～披（长条形横幅字画）。～匾。～标。～空。\n(2)左右向的，跟目视方向垂直的，与竖”、直”、纵”相对～写。～排。～向。～斜。纵～。\n(3)地理学上指东西向的与纵”相对～贯东西。\n纵；直；竖；\nhèng：(1)凶暴，不讲理；蛮～。强～。～暴。～蛮。\n(2)意外的，不寻常的～财。～祸。～事。～死。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-横"},{"id":"glyph-kai-6a31","script":"kai","character":"樱","reading":"yīng","description":"樱桃花\n樱花\n樱桃","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-樱"},{"id":"glyph-kai-6a44","script":"kai","character":"橄","reading":"gǎn","description":"gǎn：〔～榄〕ａ．常绿乔木，种子可榨油，树脂供药用。果实绿色，长圆形，亦称青果”，可食，亦可入药。ｂ．常绿小乔木，欧美用它的枝叶作为和平的象征。亦称齐墩果”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-橄"},{"id":"glyph-kai-6a58","script":"kai","character":"橘","reading":"jú；jv","description":"jú：常绿乔木，果实称橘子”，多汁，味酸甜可食。种子、树叶、果皮均可入药～红。～络。～黄色。～化为枳（喻人必然受环境的影响而发生变化）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-橘"},{"id":"glyph-kai-6a59","script":"kai","character":"橙","reading":"chéng","description":"chéng：(1)常绿乔木或灌木，果实称橙子”，多汁，品种很多，可食。皮可入药～皮。～汁。甜～。\n(2)红和黄合成的颜色～黄。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-橙"},{"id":"glyph-kai-6a61","script":"kai","character":"橡","reading":"xiàng","description":"xiàng：〔～树〕即栎（lì）树”。简称橡”，如～子”（橡树的果实）。\n〔～胶树〕常绿乔木，枝细长，三个椭圆形小叶构成复叶，开白花，结球形蒴果。简称橡”，如～皮”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-橡"},{"id":"glyph-kai-6a71","script":"kai","character":"橱","reading":"chú","description":"chú：一种收藏、放置东西的家具，前面有门～柜。书～。衣～。壁～。碗～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-橱"},{"id":"glyph-kai-6a80","script":"kai","character":"檀","reading":"tán","description":"tán：(1)落叶乔木，木质坚硬，用于制家具、乐器（亦称青檀”）。\n(2)浅绛色～口（形容红艳的嘴唇）。\n(3)姓。\n〔～香〕常绿乔木，产在热带及亚热带，木质坚硬，有香气，可制器物及香料，又可入药。\n〔紫～〕常绿乔木，木材坚硬，带红色，可制贵重家具或工艺品。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-檀"},{"id":"glyph-kai-6a90","script":"kai","character":"檐","reading":"yán","description":"yán：(1)房顶伸出墙壁的部分房～儿。廊～。飞～。前～。～沟。～头。～牙。\n(2)覆盖物的边沿或伸出的部分帽～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-檐"},{"id":"glyph-kai-6aac","script":"kai","character":"檬","reading":"méng","description":"méng：〔柠～〕见柠”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-檬"},{"id":"glyph-kai-6b20","script":"kai","character":"欠","reading":"qiàn","description":"qiàn：(1)人在疲倦时张口出气打哈～。\n(2)身体稍稍向上移动～身。\n(3)短少，不够～缺。～安。\n(4)借别人的财物没有还或应当给人的事物还没有给拖～。～账。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-欠"},{"id":"glyph-kai-6b21","script":"kai","character":"次","reading":"cì","description":"cì：(1)第二～日。～子。～等。～要。\n(2)质量、品质较差的～品。～货。\n(3)等第，顺序～第。～序。名～。\n(4)化学上指酸根或化合物中少含两个氧原子的～氯酸。\n(5)中间胸～。\n(6)量词，回～数（shù）。初～。三番五～。\n(7)旅行所居止之处所旅～。舟～。～所。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-次"},{"id":"glyph-kai-6b22","script":"kai","character":"欢","reading":"huān","description":"⒈喜悦，高兴～喜。～庆。～度。～笑。～迎。～欣。～腾。～呼。\n⒉活跃，起劲小孩子们可～。他干得真～。这部机器转得很～。〈引〉旺盛炉火正～。\n欢huàn 1.祸害;灾难。\n欢guàn 1.忧惧无处诉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-欢"},{"id":"glyph-kai-6b23","script":"kai","character":"欣","reading":"xīn","description":"xīn：快乐，喜欢～～（ａ．高兴的样子，如～～而来”；ｂ．草木生机旺盛的样子，如～～向荣”，亦泛指蓬勃发展）。～喜。欢～鼓舞。～然。～赏。～幸。～慕。～悦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-欣"},{"id":"glyph-kai-6b27","script":"kai","character":"欧","reading":"ōu","description":"通讴”。歌唱\n同驱”\n驱使;疾行\n通殴”。殴打\n通区”\n通瓯”。种族名\n欧罗巴洲的简称\n欧姆的简称\n欧ǒu 1.\"呕\"的古字。呕吐。 2.指呕吐声。 3.通\"殴\"。捶击。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-欧"},{"id":"glyph-kai-6b32","script":"kai","character":"欲","reading":"yù","description":"yù：(1)想得到某种东西或想达到某种目的的要求～念。～望。～火。食～。情～。禁～。纵～。\n(2)想要，希望～盖弥彰。～罢不能。～速不达。\n(3)需要胆～大而心～细。\n(4)能要摇摇～坠。山雨～来风满楼。\n(5)婉顺的样子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-欲"},{"id":"glyph-kai-6b3a","script":"kai","character":"欺","reading":"qī","description":"qī：(1)诈骗，蒙混～骗。～诈。～哄。～瞒。～诬。～诳。～蒙。童叟无～。\n(2)压迫，侮辱～负。～侮。～压。～凌。～生。～善怕恶。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-欺"},{"id":"glyph-kai-6b3e","script":"kai","character":"款","reading":"kuǎn","description":"kuǎn：(1)诚恳～留。～曲（qǔ）（殷勤的心意）。～待。～洽（亲切融洽）。～诚。～语（恳切谈话）。\n(2)器物上刻的字，书画、信件头尾上的名字落～（题写名字）。题～。\n(3)式样～式。\n(4)法规条文里分的项目条～。第三条第一～。\n(5)经费，钱财～项。～额。公～。存～。汇～。\n(6)敲打，叩～门。～打。～塞。～关而入。\n(7)至绕黄山而～牛首”。\n(8)留，招待～客。\n(9)空～言不听，奸乃不生”。\n(10)缓慢～步。～～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-款"},{"id":"glyph-kai-6b47","script":"kai","character":"歇","reading":"xiē","description":"xiē：(1)休息～憩。～脚。～晌。安～。～凉。～心。\n(2)停止～止。～业。～工。停～。间～。～班。～后语。\n(3)很短的一段时间过了一～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-歇"},{"id":"glyph-kai-6b49","script":"kai","character":"歉","reading":"qiàn","description":"qiàn：(1)觉得对不住人～意。～疚。抱～。道～。\n(2)收成不好～年。～岁。～收。以丰补～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-歉"},{"id":"glyph-kai-6b4c","script":"kai","character":"歌","reading":"gē","description":"gē：(1)唱～唱。～咏。～颂。～坛。～台舞榭。～舞。能～善舞。\n(2)能唱的文词唱～。～谱。～词。～诀。民～。诗～。～行（xíng）（旧诗的一种体裁，音节、格律比较自由）。诗言志，～咏言。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-歌"},{"id":"glyph-kai-6b62","script":"kai","character":"止","reading":"zhǐ","description":"zhǐ：(1)停住不动～步。截～。\n(2)拦阻，使停住～痛。禁～。\n(3)仅，只～有此数。不～一回。\n(4)古同趾”，脚；脚趾头。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-止"},{"id":"glyph-kai-6b63","script":"kai","character":"正","reading":"zhèng；zhēng","description":"zhèng：不偏斜，符合标准；端正，改正；正在。zhēng：用于正月。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-6b64","script":"kai","character":"此","reading":"cǐ","description":"cǐ：(1)这，这个，与彼”相对～间。～后。～生。长～以往（老是这样下去）。从～。因～。\n(2)这里，这儿到～为止。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-此"},{"id":"glyph-kai-6b65","script":"kai","character":"步","reading":"bù","description":"bù：(1)行走～兵。～行（xíng）。徒～。信～。闲～。固～自封。望而却～。\n(2)踏着别人的足迹走，追随～韵。～其后尘。～武前贤。\n(3)行走时两脚的距离～伐。～测。寸～难行。\n(4)事情进行的程序、阶段、程度～骤。初～。\n(5)中国旧制长度单位，一步等于五尺。\n(6)古同埠”，多用于地名。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-步"},{"id":"glyph-kai-6b66","script":"kai","character":"武","reading":"wǔ","description":"wǔ：(1)关于军事或技击的，与文”相对～装。～器。～警。～林。～坛。～生。～旦。～丑。～净。～举。\n(2)勇猛，猛烈英～。威～。～断。～士。～夫。\n(3)半步，泛指脚步步～。踵～。行（xíng）不数～。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-武"},{"id":"glyph-kai-6b67","script":"kai","character":"歧","reading":"qí","description":"qí：(1)岔道，偏离正道的小路～途（岔道，喻错误的道路，如误入～～”）。\n(2)不相同，不一致～义。～视。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-歧"},{"id":"glyph-kai-6b6a","script":"kai","character":"歪","reading":"wāi","description":"wāi：(1)不正，偏斜～斜。～曲（qū）。\n(2)不正当，不正派的～理。～诗。～才。～风。\n(3)侧卧休息我～一会儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-歪"},{"id":"glyph-kai-6b79","script":"kai","character":"歹","reading":"dǎi","description":"dǎi：不好、坏、恶～人。～意。～毒（阴险狠毒）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-歹"},{"id":"glyph-kai-6b7b","script":"kai","character":"死","reading":"sǐ","description":"sǐ：(1)丧失生命，与生”、活”相对～亡。～讯。～刑。～囚。～棋。～地。生离～别。～有余辜。\n(2)不顾生命～志（牺牲生命的决心）。～士（敢死的武士）。～战。\n(3)固执，坚持到底～心塌地。～卖力气。\n(4)无知觉睡得～。\n(5)不活动，不灵活～结。～理。～板。\n(6)不通达～胡同。～路一条。\n(7)过时，失去作用～文字。\n(8)极，甚乐～人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-死"},{"id":"glyph-kai-6b7c","script":"kai","character":"歼","reading":"jiān","description":"消灭，全部消除，如歼灭。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-6b83","script":"kai","character":"殃","reading":"yāng","description":"yāng：(1)祸害灾～。遭～。城门失火，～及池鱼（喻牵连受害）。\n(2)损害祸国～民。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-殃"},{"id":"glyph-kai-6b89","script":"kai","character":"殉","reading":"xùn","description":"xùn：(1)古代用人或物随葬～葬。\n(2)为某种目的而牺牲生命～国。～节。～难（nàn）。～情。～职。～道（指为坚持某种信仰或理论而牺牲自己的生命）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-殉"},{"id":"glyph-kai-6b8a","script":"kai","character":"殊","reading":"shū","description":"shū：(1)不同～途同归。悬～。\n(2)特别，很～功。～荣。～勋。特～。\n(3)断，绝～死。\n(4)超过母氏年～七十”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-殊"},{"id":"glyph-kai-6b8b","script":"kai","character":"残","reading":"cán","description":"①不完整～缺。\n②剩余的；快完了的～冬。\n③伤害；毁坏～害。\n④凶恶～忍、～酷。\n【残杯冷炙】见【残羹冷炙】。\n【残编断简】残缺不全的书籍。又作残篇断简、断编残简、断简残篇、断简残编。\n【残羹】吃剩的酒食。残羹剩饭剩菜。冷炙已凉的烤肉。又作残杯冷炙。\n【残骸】人或动物不完整的尸骨。借指残破的建筑物、机械、车辆等。\n【残年】\n①指人的晚年风烛～。\n②一年将尽的时候。\n【残篇断简】见【残编断简】。\n【残渣余孽】比喻残存的坏人，未消灭干净的邪恶势力。\n【残障】残疾。\n【残照】落日的光。蚕家蚕、柞蚕等的统称。蚕丝是纺织绸缎的重要原料。\n【蚕豆】豆科。一年生或越年生草本植物。茎方中空，花白色有紫斑。种子供食用，茎杆作饲料或肥料『代从西域传入，我国主要分布在西南、华中和华东。又叫胡豆。\n【蚕食】像蚕吃桑叶一样。比喻一步步地侵占。惭羞愧大言不～。\n【惭色】羞愧的表情。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-残"},{"id":"glyph-kai-6b96","script":"kai","character":"殖","reading":"zhí；shi","description":"zhí：(1)孳生生～。养～。繁～。～民地。\n(2)种植农～嘉谷”。\n(3)兴生财利货～（经商）。\nshi：〔骨～〕尸骨。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-殖"},{"id":"glyph-kai-6bb4","script":"kai","character":"殴","reading":"ōu","description":"同怄”。气恼\n假借为驱”。驱赶\n殴kōu 1.见\"殴蛇\"。\n殴qū 1.驱赶;驱使。\n殴ǒu 1.呕，呕吐。参见\"殴血\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-殴"},{"id":"glyph-kai-6bb5","script":"kai","character":"段","reading":"duàn","description":"duàn：(1)事物、时间的一节阶～。地～。片～。～落。\n(2)工矿企业中的行政单位工～。机务～。\n(3)围棋棋手等级的名称～位。\n(4)古同缎”，绸缎。\n(5)古同锻”，锻炼。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-段"},{"id":"glyph-kai-6bb7","script":"kai","character":"殷","reading":"yīn；yān；yǐn","description":"yīn：(1)富裕，富足～实。～阜。～富。\n(2)深厚，恳切情意甚～。～切。～勤。\n(3)众，多士与女，～其盈矣”。\n(4)盛，大～祭。\n(5)中国朝代名，商代的后期，由盘庚起称殷”～墟。\n(6)姓。\nyān：黑红色～红。\nyǐn：(1)雷声～其雷，在南山之阳”。\n(2)震动熊咆龙吟～岩泉”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-殷"},{"id":"glyph-kai-6bbf","script":"kai","character":"殿","reading":"diàn","description":"diàn：(1)高大的房屋，特指帝王所居和朝会的地方，或供奉神佛的地方宫～。宝～。金銮～。～堂。～阁。～上虎（喻敢谏之臣）。～试。\n(2)在最后～后。～军。\n〔～下〕对亲王或太子的敬称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-殿"},{"id":"glyph-kai-6bc1","script":"kai","character":"毁","reading":"huǐ","description":"huǐ：(1)破坏损害～灭。～害。～弃。销～。\n(2)烧掉烧～。焚～。\n(3)把成件的旧东西改造成别的东西一张旧桌子～成两个小凳子。\n(4)诽谤，说别人的坏话～谤。～誉。诋～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-毁"},{"id":"glyph-kai-6bc5","script":"kai","character":"毅","reading":"yì","description":"yì：果决，志向坚定而不动摇沉～。刚～。坚～。～力（坚强持久的意志）。～然。～勇。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-毅"},{"id":"glyph-kai-6bcd","script":"kai","character":"母","reading":"mǔ","description":"mǔ：(1)妈妈，娘～亲。～性。～系。慈～。～忧（称母亲去世）。\n(2)对女性长辈的称呼姑～。舅～。\n(3)雌性的，与公”相对～鸡。\n(4)事物据以产生出来的～国。～校。～音（元音）。\n(5)一套东西中间可以包含其他部分的螺丝～。子～扣。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-母"},{"id":"glyph-kai-6bcf","script":"kai","character":"每","reading":"měi","description":"měi：(1)指特定范围内的任何一个或一组～人。～回。～组。\n(2)指特定范围内逐一出现的任何一次～战必胜。～况愈下。\n(3)虽～有良朋，况也永叹”（虽有良朋好友，危难之时也只能为之长叹）。\n(4)古同们”，中国宋元代口语。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-每"},{"id":"glyph-kai-6bd2","script":"kai","character":"毒","reading":"dú；dài","description":"dú：(1)有害的性质或有害的东西～气。～性。～饵。～药。～蛇。吸～。贩～。\n(2)害，伤害～害。～化。～杀。莫予～也（没有谁能桅我，即谁也不能把我怎么样）。\n(3)凶狠，猛烈～辣。～计。～刑≥～。恶～。\n(4)恨，以为苦令人愤～。\ndài：古同玳”，玳瑁。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-毒"},{"id":"glyph-kai-6bd4","script":"kai","character":"比","reading":"bǐ","description":"bǐ：(1)较量高低、长短、远近、好坏等～赛。～附。对～。评～。\n(2)能够相匹今非昔～。无与伦～。\n(3)表示比赛双方胜负的对比三～二。\n(4)表示两个数字之间的倍数、分数等关系～例。～值。\n(5)譬喻，摹拟～如。～方。～兴（xìng）（文学写作的两种手法。比”是譬喻；兴”是烘托）。～画。～况（比照，相比）。\n(6)靠近，挨着～～（一个挨一个，如～～皆是”）。～肩继踵。～邻。鳞次栉～。\n(7)和，亲～顺。\n(8)及，等到～及。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-比"},{"id":"glyph-kai-6bd5","script":"kai","character":"毕","reading":"bì","description":"毕宿。星名。二十八宿之一,西方白虎七宿的第五宿,有星八颗。以其形状像毕网得名\n用毕猎取\n①终结；完成～业、礼～。\n②全、完全原形～露。\n③二十八宿之一。\n④姓。\n【毕达哥拉斯定理】见【勾股定理】。\n【毕恭毕敬】见【必恭必敬】。\n【毕生】一生；终生～的精力。\n【毕业论文】高等学校学生学习期满，独立撰写的带有研究性质的文章。一般要求毕业论文成绩及格，方能毕业。\n【毕业设计】高等学校各种技术科学专业学生学习期满，综合运用有关课程的理论和技术作出解决实际问题的设计。一般要求毕业设计成绩及格，方能毕业。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-毕"},{"id":"glyph-kai-6bd9","script":"kai","character":"毙","reading":"bì","description":"垮台,失败\n引申为死\n③枪毙。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-毙"},{"id":"glyph-kai-6bdb","script":"kai","character":"毛","reading":"máo","description":"máo：(1)动植物的皮上所生的丝状物～笔。羽～。～织品。～骨悚然。轻于鸿～。\n(2)像毛的东西，指谷物或草不～之地。\n(3)衣物上的霉菌老没见太阳都长～了。\n(4)粗糙，没有加工的～布。～估（粗略地估计）。～坯。\n(5)不是纯净的～利。～重。\n(6)行动急躁～躁。\n(7)惊慌失措，主意乱了把他吓～了。\n(8)小～病。～孩子。～～雨。\n(9)货币贬值钱～了。\n(10)量词，用于钱币，等于角”，一圆钱的十分之一两～钱。\n(11)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-毛"},{"id":"glyph-kai-6be1","script":"kai","character":"毡","reading":"zhān","description":"毡包\n这个时候,一个牧民匆匆忙忙钻进毡包来\n他背着毡包到野外去接回初生的羊羔\n⒈用兽毛压制而成的片状物，可作各种垫衬材料或防寒用品等～帽。～子毯。\n⒉像毡的东西油毛～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-毡"},{"id":"glyph-kai-6beb","script":"kai","character":"毫","reading":"háo","description":"háo：(1)细长而尖的毛～毛。～发（fà）。～末（喻极微小的数量或部分）。丝～。\n(2)指毛笔挥～。～素。\n(3)中国的秤或戥子上的提绳头～。二～。\n(4)中国市制计量单位，十毫等于一厘（长度、地积、重量单位）；一百平方毫等于一平方厘（面积单位）。\n(5)方言，货币单位，角、毛。\n(6)数量极少，一点儿（限用于否定式）～不费力。～无二致。\n(7)与某一物理量的单位连用时，表示该量的千分之一～米（公制长度单位，米”的千分之一。）","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-毫"},{"id":"glyph-kai-6bef","script":"kai","character":"毯","reading":"tǎn","description":"tǎn：厚实有毛绒的成片织品～子。毛～。床～。地～。挂～。壁～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-毯"},{"id":"glyph-kai-6c0f","script":"kai","character":"氏","reading":"shì；zhī","description":"shì：(1)古代姓”和氏”分用。姓是总的，氏是分支，后来姓和氏不分，可以混用。\n(2)古代称呼帝王贵族等，后称呼名人、专家神农～。太史～。摄～表。\nzhī：〔阏（yān）～〕见阏”。\n〔月～〕见月”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-氏"},{"id":"glyph-kai-6c11","script":"kai","character":"民","reading":"mín","description":"mín：(1)以劳动群众为主体的社会基本成员人～。～主。～国。～法。公～（在一国内有国籍，享受法律上规定的公民权利并履行公民义务的人）。国～（具有国籍的人）。\n(2)指人或人群居～。～族。\n(3)劳动大众的，非官方的～间。～歌。～谚。～风。～情。\n(4)某族的人汉～。回～。\n(5)从事不同职业的人农～。渔～。\n(6)非军事的～品。～航。\n(7)同苠”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-民"},{"id":"glyph-kai-6c13","script":"kai","character":"氓","reading":"máng；méng","description":"méng：古代称民（特指外来的）～隶（充当隶役的平民）。群～。\nmáng：〔流～〕见流”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-氓"},{"id":"glyph-kai-6c14","script":"kai","character":"气","reading":"qì","description":"此天子气也。\n气体的通称\n⒈无一定形状，能自由散布的物体～体。煤～。水蒸～。特指空气～压。吸～。\n⒉呼吸～息。～喘。屏～。上～不接下～。\n⒋闻到的味儿～味。香～。烟～。\n⒌人的精神状态、作风、风度、力量等朝～。骄～。怒～。娇～。勇～。～宇。～节。～魄。\n⒍怒，使人发怒生～。不要～我嘛！\n⒎欺负，欺压受～。\n⒏气势，气氛～壮山河。喜～洋洋。\n⒐中医指体内具有某种功能的物质～虚。～血两亏。也指某种症象湿～。痰～。\n⒑迷信者所谓的\"命运\"～数、运～等都是无稽之谈。\n①云气。\n②某种环境中反映出来的状态情景和谐的～氛。\n气xì 1.馈赠粮饷。 2.指食物。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-气"},{"id":"glyph-kai-6c1b","script":"kai","character":"氛","reading":"fēn","description":"fēn：气，气象，情势气～。～围（周围的气氛和情调）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-氛"},{"id":"glyph-kai-6c22","script":"kai","character":"氢","reading":"qīng","description":"化学元素名。一价非金属元素。在正常情况下,氢是无色、无臭、极易燃烧的双原子气体,在地球上和地球大气中只存在极稀少的游离状态氢\n燃料。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-氢"},{"id":"glyph-kai-6c27","script":"kai","character":"氧","reading":"yǎng","description":"yǎng：一种气体元素，无色、无味、无臭。氧在冶金工业、化学工业中用途很广，也是人和动、植物呼吸所必需的气体～化。臭～。输～。～割。～化焰。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-氧"},{"id":"glyph-kai-6c28","script":"kai","character":"氨","reading":"ān","description":"ān：一种无机化合物，可制人造冰，亦可制硝酸、肥料和炸药，医药上用来做兴奋剂～基。～基酸。～水。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-氨"},{"id":"glyph-kai-6c2e","script":"kai","character":"氮","reading":"dàn","description":"dàn：一种气体元素，无色、无臭、无味，化学性质不活泼。是植物营养的重要成分之一～肥。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-氮"},{"id":"glyph-kai-6c2f","script":"kai","character":"氯","reading":"lǜ","description":"等和其他有机化学工业方面也有很大用途。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-氯"},{"id":"glyph-kai-6c34","script":"kai","character":"水","reading":"shuǐ","description":"自然界中的水，也常用来指河流。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-kai-6c38","script":"kai","character":"永","reading":"yǒng","description":"yǒng：(1)水流长江之～矣”。\n(2)久远～远。～生。隽～。～昼（长昼）。～年（ａ．整年；ｂ．长寿）。～诀。～志不忘。～垂不朽。\n(3)古同咏”，以诗词等来叙述。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-永"},{"id":"glyph-kai-6c41","script":"kai","character":"汁","reading":"zhī","description":"zhī：混有某种物质的水～液。墨～。果～。胆～。脑～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汁"},{"id":"glyph-kai-6c42","script":"kai","character":"求","reading":"qiú","description":"qiú：(1)设法得到～生。～成。～知。～索。～证（寻求证据，求得证实）。～实（讲求实际）。～同存异。～全责备。～贤若渴。实事～是。\n(2)恳请，乞助～人。～告。～乞。～医。～教。～助。\n(3)需要需～。供过于～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-求"},{"id":"glyph-kai-6c47","script":"kai","character":"汇","reading":"huì","description":"用外币或本国货币兑换的票据\n收集、分类和分送各种信息或其它需要广泛分送的情况或项目\n能汇\n中子汇\n河流会合\n迂回,围绕\n以即期汇票、\n⒈水流会合～成江河。\n⒉从甲地寄款到乙地～款。～兑。电～。\n⒊外汇多出口，多创～。\n⒋综合，聚合。会聚在一起～集。～编。词～。总～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汇"},{"id":"glyph-kai-6c49","script":"kai","character":"汉","reading":"hàn","description":"汉水，长江支流；汉朝的简称；汉族及汉语的简称；成年男子，如好汉。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-6c57","script":"kai","character":"汗","reading":"hàn；hán","description":"hàn：(1)由身体的毛孔排泄出来的液体～水。～流浃背。\n(2)出汗，使出汗～颜（因羞惭而出汗；泛指惭愧）。～马功劳。～牛充栋。\nhán：〔可（kè）～〕见可2”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汗"},{"id":"glyph-kai-6c5b","script":"kai","character":"汛","reading":"xùn","description":"xùn：(1)江河定期的涨水～期。～情。防～。桃花～（桃花盛开时发生的河水暴涨。亦称桃汛”）。\n(2)洒～扫（ａ．洒扫；ｂ．扫除，清除）。\n(3)古同讯”～地（中国清代兵制，凡千总、把总、外委所统率的绿营兵均称汛”，其驻防巡逻的地区称汛地”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汛"},{"id":"glyph-kai-6c5d","script":"kai","character":"汝","reading":"rǔ","description":"rǔ：(1)你～辈。～等。～曹。～将何经。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汝"},{"id":"glyph-kai-6c5e","script":"kai","character":"汞","reading":"gǒng","description":"gǒng：一种金属元素，通常是银白色液体，俗称水银”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汞"},{"id":"glyph-kai-6c5f","script":"kai","character":"江","reading":"jiāng","description":"较大的河流。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-kai-6c60","script":"kai","character":"池","reading":"chí","description":"chí：(1)水塘，多指人工挖的～子。水～。～鱼之殃（喻因牵连而受到的灾祸。亦称池鱼之祸”）。\n(2)湖～盐（从咸水湖采取的盐，成分和海盐相同）。\n(3)像水池的浴～。花～。乐（yuè）～。舞～。\n(4)护城河城～。金城汤～。\n(5)旧时指剧场中正厅前部～座。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-池"},{"id":"glyph-kai-6c61","script":"kai","character":"污","reading":"wū","description":"wū：(1)浑浊的水粪～。血～。\n(2)肮脏，不干净～水。～泥。～浊。\n(3)肮脏的东西～渍。～垢。\n(4)不廉洁贪～。\n(5)弄脏玷～。～损。～辱。～蔑（ａ．玷污；ｂ．诬蔑）。～染。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-污"},{"id":"glyph-kai-6c64","script":"kai","character":"汤","reading":"tāng","description":"⒈热水，开水赴～蹈火。\n⒉烹调时加水汁多的副食蛋花～。什锦～。\n⒊煮食品的汁液米～。菜～。肉～。\n⒋中药汤剂～药。柴胡～。四物～。\n汤tàng 1.高温物体与皮肤接触而使之产生疼痛感。 2.把肉﹑菜放进开水里稍微煮一下就取出来。 3.泛指煮。 4.用开水或热水浇﹑泡。 5.用热物接触冷物使之变暖。\n6.冲撞;冒。 7.搪，抵挡。 8.触，碰。 9.用同\"淌\"。 10.用同\"趟\"。参见\"汤汤儿\"。 11.通\"荡\"。行为放纵。 12.通\"荡\"。大。参见\"汤禹\"。 13.通\"荡\"。荡涤\n汤shāng 1.见\"汤汤\"。\n汤yáng 1.见\"汤谷\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汤"},{"id":"glyph-kai-6c6a","script":"kai","character":"汪","reading":"wāng","description":"wāng：(1)深广～洋大海。\n(2)液体聚集在一个地方地上～着水。～～（ａ．眼里充满眼泪的样子；ｂ．象声词，形容狗叫声）。\n(3)量词，用于液体一～水。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汪"},{"id":"glyph-kai-6c70","script":"kai","character":"汰","reading":"tài","description":"tài：(1)淘洗裁～。删～。淘～（除去没有用的成分）。\n(2)骄奢，过分～侈（过分骄奢）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汰"},{"id":"glyph-kai-6c79","script":"kai","character":"汹","reading":"xiōng","description":"xiōng：〔～～〕ａ．波涛声，如波声～～”。ｂ．形容喧扰，如天下～～”，议论～～”；ｃ．形容声势很大（含贬义），如气势～～”，来势～～”。\n〔～涌〕水势很大，向上涌，如波涛～～”、～～澎湃”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汹"},{"id":"glyph-kai-6c7d","script":"kai","character":"汽","reading":"qì","description":"qì：(1)蒸气，液体或固体变成的气体～车。～灯。～化。\n(2)特指水蒸气～船。～笛。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汽"},{"id":"glyph-kai-6c81","script":"kai","character":"沁","reading":"qìn","description":"qìn：(1)渗入；浸润～润。～人心脾。\n(2)汲水义泉虽至近，盗索不敢～”。\n(3)头向下垂～着头。\n(4)纳入水中。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沁"},{"id":"glyph-kai-6c83","script":"kai","character":"沃","reading":"wò","description":"wò：(1)土地肥～土。～饶（土地肥沃，物产丰富）。～腴。肥～。～野。～壤。\n(2)灌溉，浇～田。～盥。如汤～雪。\n(3)光盛，丰美～～。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沃"},{"id":"glyph-kai-6c88","script":"kai","character":"沈","reading":"shěn；chén","description":"chén：同沉”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沈"},{"id":"glyph-kai-6c89","script":"kai","character":"沉","reading":"chén","description":"chén：(1)没（mò）入水中，与浮”相对～没。～渣。～浮（喻盛衰消长）。石～大海。～鱼落雁。静影～璧。\n(2)落下，陷入～陷。\n(3)重量大～重。\n(4)慎重，不轻浮～着（zhuó）。～毅。\n(5)深切长久，程度深～思。～滞。～吟。～默。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沉"},{"id":"glyph-kai-6c90","script":"kai","character":"沐","reading":"mù","description":"mù：(1)洗头发～浴。栉风～雨（喻辛苦奔波，饱经风雨）。\n(2)润泽，或受润泽～恩。\n(3)古代官员休假～日。休～。\n(4)整治助之～椁。\n(5)米汁。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沐"},{"id":"glyph-kai-6c99","script":"kai","character":"沙","reading":"shā；shà","description":"shā：(1)非常细碎的石粒～子。～石。风～。～尘。～砾（沙和碎石块）。～漠。～丘。～滩。～洲（江河里由泥沙淤积成的陆地）。～暴。～浴。～疗。～鸥（文学上指栖息岸边沙地的鸥一类的水鸟）。\n(2)像沙的东西～糖。豆～。～瓤。\n(3)声音不清脆不响亮～哑。\n(4)姓。\nshà：经过摇动把某东西里的杂物集中，以便清除。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沙"},{"id":"glyph-kai-6c9b","script":"kai","character":"沛","reading":"pèi","description":"pèi：(1)水势湍急，行动迅疾的样子～然。～～。\n(2)充盛的样子充～。丰～。\n(3)有水有草的地方。\n(4)跌倒，倾仆颠～（挫折困顿）。\n(5)古同旆”，旌旗。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沛"},{"id":"glyph-kai-6c9f","script":"kai","character":"沟","reading":"gōu","description":"泛指水道\n兵法曰\n⒈田间的水沟，泛指小的流水道水～。阴～。阳～。～渠。\n⒉类似沟的瓦～。交通～。\n沟kòu 1.见\"沟瞀\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沟"},{"id":"glyph-kai-6ca1","script":"kai","character":"没","reading":"méi；mò","description":"méi：(1)无～有。～用。～关系。～词儿。～精打采。～心～肺。\n(2)不曾，未～有来过。\n(3)不够，不如汽车～飞机快。\n出；有；\nmò：(1)隐在水中沉～。～顶之灾。\n(2)隐藏，消失埋～。～落。\n(3)漫过，高过水～了头顶。淹～。\n(4)财物收归公有或被私人侵吞～收。抄～。\n(5)终，尽～世。～齿不忘。\n(6)同殁”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-没"},{"id":"glyph-kai-6ca5","script":"kai","character":"沥","reading":"lì","description":"水、泪、酒等液体下滴\n从毛孔或裂缝小口慢慢流出\n倾洒\n⒈滤把水～干。\n⒉滴下～酒。\n⒊液体的点滴余～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沥"},{"id":"glyph-kai-6ca6","script":"kai","character":"沦","reading":"lún","description":"从流而风曰沦。沦,文貌。”\n沉沦;没落\n灭亡;丧亡\n⒈微波～漪。\n⒉沉，沉没沉～。\n⒊陷落～陷。～亡。\n沦lǔn 1.见\"混沦\"。\n沦guān 1.复姓用字。见\"泠沦\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沦"},{"id":"glyph-kai-6ca7","script":"kai","character":"沧","reading":"cāng","description":"同凔”‘冷\n通苍”。水深绿色\n州名\n【沧海桑田】大海变成农田，农田变为大海。比喻世事变化很大。\n【沧海一粟】大海里的一颗谷粒。比喻非常渺小集体的力量是无穷的，个人的力量只不过是～。\n【沧桑】'沧海桑田'的略语历尽～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沧"},{"id":"glyph-kai-6caa","script":"kai","character":"沪","reading":"hù","description":"捕鱼的竹栅\n上海的简称\n⒈上海的简称。因境内的吴松江下流古称\"沪渎\"而得名。\n⒉捕鱼的竹栅。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沪"},{"id":"glyph-kai-6cab","script":"kai","character":"沫","reading":"mò","description":"mò：(1)液体形成的许多细泡～子。泡～。\n(2)指唾沫”相濡以～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沫"},{"id":"glyph-kai-6cae","script":"kai","character":"沮","reading":"jǔ；jù；jv","description":"jǔ：(1)阻止～遏。\n(2)坏，败坏～丧（sàng）（失意，懊丧）。色～。力竭功～。\njù：〔～洳〕低湿的地带。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沮"},{"id":"glyph-kai-6cb3","script":"kai","character":"河","reading":"hé","description":"hé：(1)水道的通称～道。～沟。～谷。～流。～滩。～沿。～鲜（供食用的新鲜河鱼、河虾等）。～港。～湾。～网。～运。内～。\n(2)特指中国黄河～套。～防。\n(3)指银河系”天～。～汉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-河"},{"id":"glyph-kai-6cb8","script":"kai","character":"沸","reading":"fèi","description":"fèi：(1)开，滚，液体受热到一定温度时，内部发生气泡，表面翻滚，变成蒸气～点。～水。～涌。～腾（亦喻事物蓬勃发展或情绪高涨）。～反盈天（形容人声喧闹，乱成一片）。人声鼎～。\n(2)波涌的样子～郁（ａ．翻涌的样子；ｂ．愤懑不平的样子）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沸"},{"id":"glyph-kai-6cb9","script":"kai","character":"油","reading":"yóu","description":"yóu：(1)动植物体内所含的脂肪或矿产的碳氢化合物的混和液体，一般不溶于水，容易燃烧～饼。～布。～彩。～画。～亮。～水（亦指不正常的收益或额外好处）。～轮。～垢。奶～。石～。食～。汽～。添～加醋。\n(2)用油或漆涂抹～刷（ａ．涂抹油、漆；ｂ．涂抹油、漆的刷子）。\n(3)被油弄脏衣服～了一大片。\n(4)狡猾～滑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-油"},{"id":"glyph-kai-6cbb","script":"kai","character":"治","reading":"zhì","description":"zhì：(1)管理，处理～理。～家。～丧。～标。～本。～国安邦。自～。统～（ａ．管理；ｂ．分配）。\n(2)整理～河。～水。\n(3)惩办～罪。处（chǔ）～。\n(4)医疗～病。～疗。医～。\n(5)消灭农作物的病虫害～蝗。～蚜虫。\n(6)从事研究～学。～史。\n(7)安定～世。～安（社会的秩序）。天下大～。\n(8)旧称地方政府所在地府～。～所。\n(9)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-治"},{"id":"glyph-kai-6cbc","script":"kai","character":"沼","reading":"zhǎo","description":"zhǎo：池子池～。～地。～泽。～气（化学名词，即甲烷”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沼"},{"id":"glyph-kai-6cbd","script":"kai","character":"沽","reading":"gū","description":"gū：(1)买～酒。～名钓誉。\n(2)卖待价而～。\n(3)天津市的别称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沽"},{"id":"glyph-kai-6cbe","script":"kai","character":"沾","reading":"zhān","description":"zhān：(1)浸湿～衣。～润（沾湿浸润，喻沾得利益）。\n(2)因接触而附着（zhuó）上～水。～手。～污。\n(3)染上～染。\n(4)指因凭借关系而得到～光。～包。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沾"},{"id":"glyph-kai-6cbf","script":"kai","character":"沿","reading":"yán","description":"yán：(1)顺着，照着～岸（靠近江、河、湖、海一带的地区）。～海（靠海的一带）。～街。～途。～线。\n(2)因袭相传～革（事物发展和变化的历程）。～习（因袭历来的习惯）。相～成习。～袭（依照旧例行事）。～用。\n(3)边边～。坑～∮～。\n(4)在衣服等物的边上再加一条边～个边。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沿"},{"id":"glyph-kai-6cc4","script":"kai","character":"泄","reading":"xiè；yì","description":"xiè：(1)液体或气体排出排～。～洪。～泻。\n(2)漏，露～劲。～露。～漏。～密。\n(3)尽量发出（情绪、情欲等）～愤。～恨。发～。\n鼓；\nyì：〔～～〕ａ．缓飞的样子，如雄雉于飞，～～其羽”；ｂ．闲散自得，如十亩外兮，桑者～～兮”；ｃ．弛缓的样子，如天之方噘，无然～～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泄"},{"id":"glyph-kai-6cc9","script":"kai","character":"泉","reading":"quán","description":"quán：(1)从地下流出的水源～源。～瀑。甘～。温～。喷～。黄～（旧时称人死后所在的地方。亦作九泉”）。\n(2)古代钱币的名称。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泉"},{"id":"glyph-kai-6cca","script":"kai","character":"泊","reading":"bó；pō","description":"bó：(1)停船靠岸～船。～位（航运上指港区能停靠船泊的位置）。停～。\n(2)停留飘～。\n(3)安静淡～（亦作澹泊”）。\n〔落（luò）～〕见落1”。\npō：湖湖～。水～。血～（一大滩血）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泊"},{"id":"glyph-kai-6ccc","script":"kai","character":"泌","reading":"mì；bì","description":"mì：从生物体内产生出某种物质，流质由细孔渗透出来分～。～尿。～乳。\nbì：泉流轻快的样子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泌"},{"id":"glyph-kai-6cd5","script":"kai","character":"法","reading":"fǎ","description":"fǎ：(1)体现统治阶段的意志，国家制定和颁布的公民必须遵守的行为规则～办。～典。～官。～规。～律。～令。～定。～场。～理。～纪。～盲。～人（自然人”的对称。指依法成立并能以自己的名义独立参与民事活动，享有民事权利和承担法律义务的社会组织）。～制。～治。犯～。守～∠～。宪～（国家的根本大法）。政～。奉公守～。逍遥～外。\n(2)处理事物的手段办～。设～。手～。写～。\n(3)仿效效～。\n(4)标准，规范，可仿效的～式。～帖。\n(5)佛家的道理佛～。～号。～轮。～像。～门。\n(6)道家佛家的所谓拿妖捉怪的技术～师。～器。～事。\n(7)指法国”～文。～式大菜。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-法"},{"id":"glyph-kai-6cdb","script":"kai","character":"泛","reading":"fàn","description":"fàn：(1)漂浮～舟。\n(2)透出脸上～出了红晕。\n(3)浮浅，不切实浮～。空～。～～之交（友谊不深）。～～而谈。\n(4)一般地～论。～指。～称。广～。～览。～读。\n(5)水向四处漫流～溢。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泛"},{"id":"glyph-kai-6cde","script":"kai","character":"泞","reading":"nìng","description":"按,荥泞叠韵连语,小水之貌。\n泞zhù 1.见\"澹泞\"。\n泞níng 1.见\"汀泞\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泞"},{"id":"glyph-kai-6ce1","script":"kai","character":"泡","reading":"pào；pāo","description":"pào：(1)气体在液体内使液体鼓起来的球状体～沫。～影（ａ．佛教用泡”和影”喻事物的生灭无常；ｂ．现喻落空的事情和希望）。水～。\n(2)像泡的东西电灯～儿。\n(3)用液体浸物品～茶。～菜。～饭。～汤（喻事情或愿望落空）。\n(4)故意消磨时间～病号。\npāo：(1)鼓起而松软的东西眼～。豆腐～儿。\n(2)虚而松软，不坚硬～桐。这块木料发～。\n(3)方言，小湖（多用于地名）～子。月亮～（在中国吉林省）。\n(4)同脬”，量词。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泡"},{"id":"glyph-kai-6ce2","script":"kai","character":"波","reading":"bō","description":"bō：(1)水面振荡起伏的运动～浪。～涛。～澜。～光。～纹。～荡。推～助澜。～及（影响到，牵涉到）。\n(2)物理学上指振动在物质中的传播能量递进的一种形式电～。光～。超声～。～长。～段。～速。～谱。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-波"},{"id":"glyph-kai-6ce3","script":"kai","character":"泣","reading":"qì","description":"qì：(1)小声哭～诉（哭着控诉）。抽～。哭～。涕～。\n(2)眼泪饮～。～下如雨。～血（ａ．流眼泪没有声，像出血那样；ｂ．指在丧事期）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泣"},{"id":"glyph-kai-6ce5","script":"kai","character":"泥","reading":"ní；nì","description":"ní：(1)土和水合成的东西～巴。～垢。～浆。～煤。～淖（泥污的洼地）。～泞。～洼。\n(2)像泥的东西枣～。山药～。印～（盖图章用的印色）。蒜～。\nnì：(1)涂抹～墙。～缝儿（fèngr）。\n(2)固执，死板拘～。～古（拘泥古代的制度和说法，不根据具体情况加以变通）。～守。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泥"},{"id":"glyph-kai-6ce8","script":"kai","character":"注","reading":"zhù","description":"zhù：(1)灌进去～入。～射。大雨如～。\n(2)（精神、力量）集中在一点～视。～目。～意。\n(3)用文字来解释词名～解。～释。～音。夹～。\n(4)解释词句所用的文字～疏（注解和解释注解的文字的合称）。\n(5)记载，登记～册。～销。\n(6)赌博时所下金钱财物下～。赌～。\n(7)量词，多用于款项或交易一～钱。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-注"},{"id":"glyph-kai-6cea","script":"kai","character":"泪","reading":"lèi","description":"lèi：眼里流出的水眼～。～痕。～水。～眼。～珠。～盈盈。声～俱下。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泪"},{"id":"glyph-kai-6cf0","script":"kai","character":"泰","reading":"tài","description":"tài：(1)平安，安定～适（幽闲安适）。～安。～然处之。\n(2)佳，美好～运。否（pǐ）极～来。\n(3)极～西（旧指欧洲）。\n(4)骄纵，傲慢～侈（骄纵奢侈）。骄～。\n(5)通天地交～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泰"},{"id":"glyph-kai-6cf3","script":"kai","character":"泳","reading":"yǒng","description":"yǒng：在水里游动游～。蛙～。仰～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泳"},{"id":"glyph-kai-6cf5","script":"kai","character":"泵","reading":"bèng","description":"bèng：一种机器，能把液体或气体抽出或压入水～。～房（安装泵的房屋）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泵"},{"id":"glyph-kai-6cfb","script":"kai","character":"泻","reading":"xiè","description":"倾泻\n倾注;倾倒\n排泄\n⒈急流，很快地流一～千里。一～无余。\n⒉拉稀大便腹～。上吐下～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泻"},{"id":"glyph-kai-6cfc","script":"kai","character":"泼","reading":"pō","description":"淹死\n⒈浇，泻，猛倒～水。瓢～大雨。\n⒉蛮横，不讲理撒～。\n①凶狠不讲理那是个～辣货。\n②勇猛有魄力大胆～辣。\n泼bō 1.见\"泼泼\"。 2.量词。同\"拨\"。相当于\"番\"。 3.量词。同\"拨\"。相当于\"群\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泼"},{"id":"glyph-kai-6cfd","script":"kai","character":"泽","reading":"zé","description":"水深\n⒈聚积水的地方沼～〓～。深山大～。\n⒉湿，雨露润～。雨～。\n⒊恩惠恩～。\n⒋金属或别的物体发出的光亮光～。色～。\n泽shì 1.通\"释\"。松散，解散。 2.通\"舍\"。\n泽yì 1.通\"醳\"。酒。 2.通\"怿\"。乐。\n泽duó 1.见\"格泽\"。 2.通\"?","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泽"},{"id":"glyph-kai-6d01","script":"kai","character":"洁","reading":"jié","description":"操行清白,品德高尚\n以著其洁","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洁"},{"id":"glyph-kai-6d0b","script":"kai","character":"洋","reading":"yáng","description":"yáng：(1)比海更大的水域海～。\n(2)广大，众多，丰盛～溢。～～。\n(3)指外国的，外国来的～人。～货。～为中用。\n(4)指现代化的（区别于土”）土～结合。\n(5)银元大～。～钱。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洋"},{"id":"glyph-kai-6d12","script":"kai","character":"洒","reading":"sǎ；xǐ","description":"xǐ：古同洗”，洗涤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洒"},{"id":"glyph-kai-6d17","script":"kai","character":"洗","reading":"xǐ；xiǎn","description":"xǐ：(1)用水去掉污垢～脸。～涮。～涤。～澡。～心革面（喻彻底悔改）。\n(2)清除干净清～。\n(3)像水洗一样抢光，杀光～劫。\n(4)昭雪冤枉～雪。～冤。\n(5)照相的显影定影冲～。～印。\n(6)玩牌时把牌搀和整理～牌。\n(7)基督教接受个人入教时的仪式受～。～礼。\n(8)盛水洗笔的器皿笔～。\n(9)把磁带上的录音或录像去掉。\nxiǎn：同冼”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洗"},{"id":"glyph-kai-6d1b","script":"kai","character":"洛","reading":"luò","description":"luò：〔～河〕水名，在中国陕西省。\n〔～水〕水名，源于中国陕西省洛南县，东流经河南省入黄河。古作雒”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洛"},{"id":"glyph-kai-6d1e","script":"kai","character":"洞","reading":"dòng","description":"dòng：(1)窟窿，深穴，孔～穴。山～。～箫。空～。漏～。～府。～天。\n(2)打洞，打成洞（穿透）一狼～其中。\n(3)透彻地，清楚地～悉。～穿。\n(4)说数字时用来代替零。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洞"},{"id":"glyph-kai-6d25","script":"kai","character":"津","reading":"jīn","description":"jīn：(1)渡水的地方～渡。关～。～要。问～。\n(2)口液，唾液～液。～～有味。\n(3)汗遍体生～。\n(4)滋润，补～润。～贴。\n(5)中国天津市的简称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-津"},{"id":"glyph-kai-6d2a","script":"kai","character":"洪","reading":"hóng","description":"hóng：(1)大～水。～大。～福。～荒。～亮。\n(2)大水山～。蓄～。分～。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洪"},{"id":"glyph-kai-6d32","script":"kai","character":"洲","reading":"zhōu","description":"zhōu：(1)水中的陆地沙～。～渚。\n(2)大陆及其附属岛屿的总称七大～。～际导弹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洲"},{"id":"glyph-kai-6d3b","script":"kai","character":"活","reading":"huó","description":"huó：(1)生存，有生命的，能生长，与死”相对～人。～体。～检。～物。\n(2)救活，使人活～人无数。\n(3)在活的状态下～埋。\n(4)逼真地～脱。～像。\n(5)不固定，可移动，或处在进去状态的～塞（sāi）。～扣。～页本。耳软心～（没主见）。\n(6)生动，不呆板，机灵，有生气～力。\n(7)工作或生产品～儿。～计。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-活"},{"id":"glyph-kai-6d3c","script":"kai","character":"洼","reading":"wā","description":"wā：(1)凹陷的地方水～儿。～子。\n(2)低凹，深陷～地。眼眶～进去。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洼"},{"id":"glyph-kai-6d3d","script":"kai","character":"洽","reading":"qià","description":"qià：(1)跟人联系，商量面～。接～。\n(2)谐和融～。\n(3)广博，周遍博识～闻。\n(4)沾湿，浸润内～五脏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洽"},{"id":"glyph-kai-6d3e","script":"kai","character":"派","reading":"pai；pài","description":"pài：(1)水的支流九～（指长江支流之多）。\n(2)一个系统的分支～系。～别。～性。党～。\n(3)作风，风度正～。气～。～势。～头。\n(4)分配，指定～赴。～驻。～遣。委～。\n(5)指摘～不是。\n(6)量词（ａ．用于派别，如两～的意见争论不休”；ｂ．用于景色、气象、语言等，前面用一”字，如一～胡言”、好一～北国风光”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-派"}];
